  function normalizeSharedFactionMembersPayload(
    payload
  ) {
    const raw =
      payload?.members ||
      payload?.faction?.members ||
      [];

    if (!Array.isArray(raw)) {
      return {
        ...payload,
        members: raw || {}
      };
    }

    const members = {};
    for (const member of raw) {
      const id =
        member?.id ??
        member?.user_id ??
        member?.player_id;

      if (!/^\d+$/.test(String(id ?? ""))) {
        continue;
      }

      members[String(id)] = member;
    }

    return {
      ...payload,
      members
    };
  }

  function sharedFactionMembersRequest(
    url
  ) {
    return new Promise((resolve, reject) => {
      const request =
        typeof GM_xmlhttpRequest === "function"
          ? GM_xmlhttpRequest
          : (
              typeof GM !== "undefined" &&
              typeof GM.xmlHttpRequest ===
                "function"
                ? options =>
                    GM.xmlHttpRequest(options)
                : null
            );

      if (!request) {
        reject(
          new Error(
            "Torn API request helper unavailable"
          )
        );
        return;
      }

      request({
        method: "GET",
        url,
        timeout: 20000,
        headers: {
          Accept: "application/json"
        },
        onload(response) {
          try {
            const payload =
              JSON.parse(
                response.responseText || "{}"
              );

            if (
              response.status < 200 ||
              response.status >= 300
            ) {
              reject(
                new Error(
                  `Torn API HTTP ${response.status}`
                )
              );
              return;
            }

            if (payload?.error) {
              reject(
                new Error(
                  payload.error.error ||
                    payload.error.message ||
                    "Torn API error"
                )
              );
              return;
            }

            resolve(
              normalizeSharedFactionMembersPayload(
                payload
              )
            );
          } catch (error) {
            reject(error);
          }
        },
        onerror() {
          reject(
            new Error(
              "Torn faction members request failed"
            )
          );
        },
        ontimeout() {
          reject(
            new Error(
              "Torn faction members request timed out"
            )
          );
        }
      });
    });
  }

  async function getSharedFactionMembersPayload(
    apiKey,
    factionId = "",
    force = false
  ) {
    const key =
      String(apiKey || "").trim();

    if (!key) {
      throw new Error(
        "API key not configured"
      );
    }

    const faction =
      String(factionId || "").trim();

    const cacheKey =
      `${faction || "own"}:${key}`;

    const cached =
      sharedFactionMembersApi.cache.get(
        cacheKey
      );

    if (
      !force &&
      cached?.timestamp &&
      Date.now() - cached.timestamp <
        sharedFactionMembersApi.ttl
    ) {
      return cached.payload;
    }

    const existing =
      sharedFactionMembersApi.inflight.get(
        cacheKey
      );

    if (existing) {
      return existing;
    }

    const endpoint = faction
      ? `https://api.torn.com/v2/faction/${encodeURIComponent(faction)}/members?striptags=true&key=${encodeURIComponent(key)}`
      : `https://api.torn.com/v2/faction/members?striptags=true&key=${encodeURIComponent(key)}`;

    const promise =
      sharedFactionMembersRequest(endpoint)
        .then(payload => {
          sharedFactionMembersApi.cache.set(
            cacheKey,
            {
              timestamp: Date.now(),
              payload
            }
          );
          return payload;
        })
        .finally(() => {
          sharedFactionMembersApi.inflight.delete(
            cacheKey
          );
        });

    sharedFactionMembersApi.inflight.set(
      cacheKey,
      promise
    );

    return promise;
  }

