  function readStageScanState() {
    const saved = loadLS(STAGE_SCAN_STATE_KEY) || {};

    return {
      Recruiting: {
        completed:
          !!saved?.Recruiting?.completed,
        scannedAt:
          Number(
            saved?.Recruiting?.scannedAt || 0
          )
      },
      Planning: {
        completed:
          !!saved?.Planning?.completed,
        scannedAt:
          Number(
            saved?.Planning?.scannedAt || 0
          )
      }
    };
  }

  function writeStageScanState(stateValue) {
    saveLS(STAGE_SCAN_STATE_KEY, stateValue);
  }

  const sessionScanState = {
    Recruiting: false,
    Planning: false
  };

  function markStageScanRequired(stage) {
    if (
      stage !== "Recruiting" &&
      stage !== "Planning"
    ) {
      return;
    }

    sessionScanState[stage] = false;

    const state =
      readStageScanState();

    state[stage] = {
      ...state[stage],
      completed: false
    };

    writeStageScanState(state);
  }

  function markStageScanComplete(stage) {
    if (
      stage !== "Recruiting" &&
      stage !== "Planning"
    ) {
      return;
    }

    sessionScanState[stage] = true;

    const state =
      readStageScanState();

    state[stage] = {
      completed: true,
      scannedAt: now()
    };

    writeStageScanState(state);
  }
