function parseNumFld(id){const v=parseFloat(document.getElementById(id)?.value||"0");return isFinite(v)?v:0;}
function setPayTxt(id,v){const el=document.getElementById(id);if(el)el.textContent=v??"";}
function setPayHtml(id,h){const el=document.getElementById(id);if(el)el.innerHTML=h??"";}
function setPayFld(id,v){const el=document.getElementById(id);if(el)el.value=v??"";}
function brGetHighestStat(stats){return[["Manual Labor",stats.M||0],["Intelligence",stats.I||0],["Endurance",stats.E||0]].sort((a,b)=>b[1]-a[1])[0];}
function brGetPrimaryStat(req,stats){const first=Object.keys(req||{})[0]||"M";if(first==="I")return{label:"Intelligence",value:stats.I||0};if(first==="E")return{label:"Endurance",value:stats.E||0};return{label:"Manual Labor",value:stats.M||0};}
function brCalcPay(roleName,req,stats,mods){const{merits,meritRate,settled,settledRate,dirEd,dirEdRate,addiction,addictionRate,inactive,inactiveRate,adjustment,rate,mode}=mods;const basePay=mods.basePay||0;const fit=brScoreRole(stats,req||{}).score;const totalEff=Math.max(0,Math.round((fit*100)+merits+settled+dirEd-addiction-inactive));let effectPay=0,calcText="-";const hs=brGetHighestStat(stats);const ps=brGetPrimaryStat(req||{},stats);if(mode==="flat"){effectPay=rate;calcText=`${rate.toLocaleString()} flat`;}else if(mode==="per_1000_primary"){effectPay=Math.round((ps.value/1000)*rate);calcText=`${ps.value.toLocaleString()}/1000 × ${rate.toLocaleString()}`;}else if(mode==="highest_stat_times"){effectPay=Math.round(hs[1]*rate);calcText=`${hs[1].toLocaleString()} × ${rate.toLocaleString()}`;}else{effectPay=Math.round(totalEff*rate);calcText=`${totalEff.toLocaleString()} × ${rate.toLocaleString()}`;}const bonusPay=(merits*meritRate)+(settled*settledRate)+(dirEd*dirEdRate);const penaltyPay=(addiction*addictionRate)+(inactive*inactiveRate);const finalPay=Math.max(0,Math.round(basePay+effectPay+bonusPay-penaltyPay+adjustment));return{fitScore:fit,totalEff,basePay,effectPay,bonusPay,penaltyPay,finalPay,calcText};}
function brGetCurReqFromModal(){const roleName=document.getElementById("fc-pay-modal")?.dataset.currentRole||"";const meta=brGetRoleSet();if(!meta.roles)return null;const want=normRole(roleName);for(const r of meta.roles){if(normRole(r.role)===want)return r.req;}return null;}
function brRenderReqFit(req,stats,roleName,companyName){if(!req){setPayHtml("fpc-req-fit",`<div style="color:var(--sakalux-textMuted)">Not detected</div>`);return;}const labels={M:"Manual Labor",I:"Intelligence",E:"Endurance"};const gains=brGetTrainGains(companyName||"",roleName||"")||[];const gainMap={M:0,I:0,E:0};gains.forEach(g=>{const m=String(g).match(/^([MIE])\s*\+(\d+)/i);if(m)gainMap[m[1].toUpperCase()]=parseInt(m[2])||0;});setPayHtml("fpc-req-fit",Object.keys(req).map(k=>{const have=Number(stats[k]||0),need=Number(req[k]||0),ok=have>=need;const pct=need>0?Math.floor((have/need)*100):0;const g=gainMap[k]||0;const missing=Math.max(0,need-have);const trainText=ok?"Requirement met":g>0?`${Math.ceil(missing/g)} train${Math.ceil(missing/g)===1?"":"s"} to qualify`:"No matching train";return`<div class="fpc-fit-item ${ok?"ok":"bad"}"><div class="fpc-fit-left"><div class="fpc-fit-stat">${labels[k]}</div><div class="fpc-fit-nums">${have.toLocaleString()} / ${need.toLocaleString()}</div><div class="fpc-fit-pct">${pct}%</div><div class="fpc-fit-trains">${trainText}</div></div><div class="fpc-fit-mark">${ok?"✔":"✖"}</div></div>`;}).join(""));}
function brRenderRoleAnalysis(stats){const meta=brGetRoleSet();const el=document.getElementById("fpc-role-analysis");if(!el||!meta.roles){if(el)el.innerHTML=`<div class="fpc-role-box" style="color:var(--sakalux-textMuted)">No role mapping detected.</div>`;return;}const roleName=document.getElementById("fc-pay-modal")?.dataset.currentRole||"";const mods=brGetMods();const allRanked=meta.roles.map(r=>{const c=brCalcPay(r.role,r.req,stats,mods);const s=brScoreRole(stats,r.req||{});return{role:r.role,req:r.req,...c,meets:s.meets,reqW:brReqWeight(r.req)};}).sort((a,b)=>b.reqW!==a.reqW?b.reqW-a.reqW:b.totalEff-a.totalEff);const qualifying=allRanked.filter(r=>r.meets);const best=qualifying.length?qualifying[0]:null;const current=allRanked.find(r=>normRole(r.role)===normRole(roleName))||allRanked[0];const alreadyBest=best&&normRole(current.role)===normRole(best.role);const effDiff=best?(best.totalEff-current.totalEff):0;el.innerHTML=`<div class="fpc-role-box"><div class="fpc-role-head">Current: ${escHtml(current.role)}</div><div class="fpc-role-line">Est. Effectiveness: ${current.totalEff.toLocaleString()}</div><div class="fpc-role-line">Suggested Pay: $${current.finalPay.toLocaleString()}</div></div><div class="fpc-role-box ${best?"best":""}"><div class="fpc-role-head">${best?`Best Qualifying Role: ${escHtml(best.role)}`:`<span style="color:var(--sakalux-orange2)">No qualifying role yet</span>`}</div>${best?`<div class="fpc-role-line">Projected Effectiveness: ${best.totalEff.toLocaleString()}</div><div class="fpc-role-line">Projected Pay: $${best.finalPay.toLocaleString()}</div><div class="fpc-role-line">Diff vs Current: ${effDiff>=0?"+":""}${effDiff.toLocaleString()}</div><div class="fpc-role-status">${alreadyBest?"Best qualifying role already assigned":`Better qualifying role: ${escHtml(best.role)}`}</div>`:`<div class="fpc-role-line">Employee stats don't meet requirements for any role. Keep training.</div>`}</div>`;}
function brGetMods(){return{merits:parseNumFld("fpc-merits"),meritRate:parseNumFld("fpc-merit-rate"),settled:parseNumFld("fpc-settled"),settledRate:parseNumFld("fpc-settled-rate"),dirEd:parseNumFld("fpc-dir-ed"),dirEdRate:parseNumFld("fpc-dir-ed-rate"),addiction:parseNumFld("fpc-addiction"),addictionRate:parseNumFld("fpc-addiction-rate"),inactive:parseNumFld("fpc-inactive"),inactiveRate:parseNumFld("fpc-inactive-rate"),adjustment:parseNumFld("fpc-adjustment"),rate:parseNumFld("fpc-rate"),basePay:parseNumFld("fpc-base-pay"),mode:document.getElementById("fpc-mode")?.value||"per_effectiveness"};}
