function brParseTip(text){const out={merits:0,settled:0,addiction:0,inactive:0,dirEd:0,workingStats:0,effectiveness:0,tags:[]};const t=normTip(text||"");[{k:"workingStats",r:/working stats\s*:\s*([+-]?\d+)/i},{k:"settled",r:/settled in\s*:\s*([+-]?\d+)/i},{k:"merits",r:/merits\s*:\s*([+-]?\d+)/i},{k:"dirEd",r:/director education\s*:\s*([+-]?\d+)/i},{k:"addiction",r:/addiction\s*:\s*([+-]?\d+)/i},{k:"inactive",r:/inactiv(?:e|ity)\s*:\s*([+-]?\d+)/i},{k:"effectiveness",r:/effectiveness\s*:\s*([+-]?\d+)/i}].forEach(p=>{const m=t.match(p.r);if(m)out[p.k]=parseInt(m[1],10)||0;});const pos=[],neg=[];if(out.workingStats>0)pos.push(`Working stats +${out.workingStats}`);if(out.settled>0)pos.push(`Settled in +${out.settled}`);if(out.merits>0)pos.push(`Merits +${out.merits}`);if(out.dirEd>0)pos.push(`Director ed +${out.dirEd}`);if(out.addiction)neg.push(`Addiction ${out.addiction>0?"-":""}${Math.abs(out.addiction)}`);if(out.inactive)neg.push(`Inactivity ${out.inactive>0?"-":""}${Math.abs(out.inactive)}`);out.tags=[...pos,...neg];if(!out.tags.length)out.tags.push("No modifiers detected");return out;}
