        const saveBtn=panel.querySelector("#tl-ne-save");if(saveBtn){saveBtn.textContent="Added ✓";setTimeout(()=>saveBtn.textContent="Add Entry",1400);}
        if(empSel)[...empSel.options].forEach(o=>o.selected=false);const noteEl=panel.querySelector("#tl-ne-note");if(noteEl)noteEl.value="";panel.querySelector("#tl-ne-trains")&&(panel.querySelector("#tl-ne-trains").value="1");panel.querySelector("#tl-ne-repeat")&&(panel.querySelector("#tl-ne-repeat").value="1");
        refreshDayPanel(dayKey,isFuture);
        refreshCalendarCells();
