    function restorePosition(panel) {
      try {
        const saved = JSON.parse(
          localStorage.getItem(POSITION_KEY)
        );
        if (!saved) throw new Error();
        panel.style.left =
          `${Math.round(saved.xPct * window.innerWidth)}px`;
        panel.style.top =
          `${Math.round(saved.yPct * window.innerHeight)}px`;
        panel.style.right = "auto";
      } catch {
        panel.style.top = "54px";
        panel.style.right = "12px";
        panel.style.left = "auto";
      }
    }
    function makeDraggable(panel) {
      const header = panel.querySelector(".tma-header");
      if (!header) return;
      let dragging = false;
      let startX = 0;
      let startY = 0;
      let initialLeft = 0;
      let initialTop = 0;
      const move = event => {
        if (!dragging) return;
        const point = event.touches?.[0] || event;
        const rect = panel.getBoundingClientRect();
        const left = Math.min(
          window.innerWidth - rect.width,
          Math.max(
            0,
            initialLeft + point.clientX - startX
          )
        );
        const top = Math.min(
          window.innerHeight - rect.height,
          Math.max(
            0,
            initialTop + point.clientY - startY
          )
        );
        panel.style.left = `${left}px`;
        panel.style.top = `${top}px`;
        panel.style.right = "auto";
      };
      const end = () => {
        if (!dragging) return;
        dragging = false;
        const rect = panel.getBoundingClientRect();
        localStorage.setItem(
          POSITION_KEY,
          JSON.stringify({
            xPct: rect.left / window.innerWidth,
            yPct: rect.top / window.innerHeight
          })
        );
        document.removeEventListener("mousemove", move);
        document.removeEventListener("mouseup", end);
        document.removeEventListener("touchmove", move);
        document.removeEventListener("touchend", end);
      };
      const start = event => {
        if (event.target.closest("button")) return;
        const point = event.touches?.[0] || event;
        const rect = panel.getBoundingClientRect();
        dragging = true;
        startX = point.clientX;
        startY = point.clientY;
        initialLeft = rect.left;
        initialTop = rect.top;
        document.addEventListener("mousemove", move);
        document.addEventListener("mouseup", end);
        document.addEventListener("touchmove", move, {
          passive: true
        });
        document.addEventListener("touchend", end);
      };
      header.addEventListener("mousedown", start);
      header.addEventListener("touchstart", start, {
        passive: true
      });
      moduleState.cleanup.push(() => {
        header.removeEventListener("mousedown", start);
        header.removeEventListener("touchstart", start);
        document.removeEventListener("mousemove", move);
        document.removeEventListener("mouseup", end);
        document.removeEventListener("touchmove", move);
        document.removeEventListener("touchend", end);
      });
      restorePosition(panel);
    }
